import sys, os; sys.path.insert(0, os.path.dirname(os.path.dirname(__file__)))
from dsl import *
U("s5-u03")
C = "B1"

L(1, "Gezelligheid", "Uma palavra difícil de traduzir.",
  ["Compreender e usar gezellig e gezelligheid"],
  vocab=[V("v-gezelligheid","gezelligheid","ambiente acolhedor e agradável","noun","de"), V("v-knus","knus","aconchegado","adjective"),
         V("v-samenzijn","samenzijn","convívio|estar juntos","noun","het"), V("v-ongezellig","ongezellig","pouco acolhedor|desagradável","adjective")],
  ex=[("Het was heel gezellig gisteravond.","Ontem à noite foi muito agradável."),("Wat een knus café!","Que café tão aconchegado!"),("Gezelligheid is belangrijk voor Nederlanders.","A «gezelligheid» é importante para os neerlandeses."),("Wat ongezellig, zo'n lege zaal.","Que desagradável, uma sala assim vazia.")],
  gram=[G("g-gezellig","O que é «gezellig»?","**gezellig** descreve um ambiente caloroso, descontraído e de convívio: uma conversa com amigos, um café com velas, uma festa de família. Usa-se para lugares, situações e pessoas: *Hij is een gezellige man.* O contrário é **ongezellig**.",
    [("Kom je ook? Gezellig!","Também vens? Que bom!")],
    "Não há palavra exata em português: fica entre «acolhedor», «agradável» e «convívio».")],
  review=["v-gezellig","v-feest","v-vriend"],
  cefr=C, exs=[
    MA([("gezelligheid","ambiente acolhedor"),("knus","aconchegado"),("samenzijn","convívio"),("ongezellig","pouco acolhedor")], "Gezelligheid.", ["v-gezelligheid","v-knus","v-samenzijn","v-ongezellig"]),
    MC("Qual situação é «gezellig»?", ["*Jantar com amigos à luz das velas a conversar","Esperar sozinho num corredor de hospital|Ongezellig.","Uma reunião tensa|Ongezellig."], "Calor humano.", ["v-gezelligheid"]),
    MC("«Kom je ook? Gezellig!» — aqui «gezellig» significa…", ["*Que bom! (vai ser agradável)","Que chato.|Ao contrário.","Tens de vir.|Não."], "Reação de alegria.", ["v-gezellig"]),
    TR("nl-pt","Het was heel gezellig gisteravond.", ["Ontem à noite foi muito agradável","Ontem à noite estava-se muito bem","Ontem à noite foi muito acolhedor"], "gezellig.", ["v-gezellig"]),
    TR("pt-nl","Que café tão aconchegado!", ["Wat een knus café","Wat een gezellig café"], "knus/gezellig.", ["v-knus"]),
    AR("samenzijn","o convívio","het", "Het samenzijn.", ["v-samenzijn"]),
    FB("Zo'n lege kamer zonder lampen vind ik ___.", ["ongezellig"], "Contrário de gezellig.", ["v-ongezellig"], choices=["ongezellig","gezellig","knus"], tr="Acho um quarto vazio sem candeeiros pouco acolhedor."),
    LI("Wat gezellig dat jullie er allemaal zijn!", ["Wat gezellig dat jullie er allemaal zijn"], "Que bom que estejam todos aqui!", "gezellig.", ["v-gezellig"]),
    FE(["Het","was","een","gezellig","avond."], 3, "gezellige", "Antes de «avond» (de-woord): gezellige.", ["v-gezellig"]),
    SW("Descreva em 2 frases uma situação que para si é «gezellig».", ["Voor mij is het gezellig als ik met vrienden kaas eet en wijn drink. Dan praten we uren en lachen we veel."], ["Usou **gezellig** corretamente", "Descreveu pessoas + ambiente", "Inversão depois de **dan**"], 12, "Gezelligheid pessoal.", ["v-gezelligheid"]),
  ], diff=4, mins=6)

L(2, "Directheid: a franqueza neerlandesa", "Eerlijk gezegd… Dat vind ik geen goed idee.",
  ["Compreender a comunicação direta e responder adequadamente"],
  vocab=[V("v-direct","direct","direto","adjective"), V("v-eerlijk-gezegd","eerlijk gezegd","para ser sincero","expression"),
         V("v-bot","bot","bruto|rude","adjective"), V("v-kritiek","kritiek","crítica","noun","de")],
  ex=[("Eerlijk gezegd vind ik het te duur.","Para ser sincero, acho demasiado caro."),("Nederlanders zijn vaak heel direct.","Os neerlandeses são muitas vezes muito diretos."),("Dat klonk een beetje bot.","Isso soou um bocado rude."),("Ik kan goed tegen kritiek.","Lido bem com críticas.")],
  gram=[G("g-directheid-cultuur","Ser direto ≠ ser rude","Muitos neerlandeses dizem o que pensam sem rodeios: *Dat vind ik geen goed idee.* Não é falta de respeito; é honestidade e eficiência. Pode responder da mesma forma, com argumentos. **Eerlijk gezegd** e **Om eerlijk te zijn** anunciam uma opinião franca.",
    [("Om eerlijk te zijn: je presentatie was te lang.","Para ser sincero: a tua apresentação foi demasiado longa.")],
    "Em Portugal suaviza-se mais; nos Países Baixos a crítica direta é frequentemente vista como sinal de confiança.")],
  review=["v-mening","v-volgens-mij","v-oneens"],
  cefr=C, exs=[
    MA([("direct","direto"),("eerlijk gezegd","para ser sincero"),("bot","rude"),("kritiek","crítica")], "Franqueza.", ["v-direct","v-eerlijk-gezegd","v-bot","v-kritiek"]),
    TR("pt-nl","Para ser sincero, acho demasiado caro.", ["Eerlijk gezegd vind ik het te duur","Eerlijk gezegd vind ik het veel te duur"], "Inversão depois de eerlijk gezegd.", ["v-eerlijk-gezegd"]),
    TR("nl-pt","Ik kan goed tegen kritiek.", ["Lido bem com críticas","Aceito bem críticas","Lido bem com a crítica"], "tegen iets kunnen.", ["v-kritiek"]),
    MC("O chefe diz: «Dit rapport is niet goed genoeg.» Isto é…", ["*feedback normal e direto, para melhorar","um insulto pessoal|Não é a intenção habitual.","um despedimento|Não."], "Directheid.", ["v-direct"]),
    MC("Boa resposta a essa crítica:", ["*Oké, wat moet er beter volgens jou?","Hoe durf je!|Exagerado.","(silêncio e ficar ofendido)|Não ajuda."], "Pedir concretização.", ["v-kritiek"]),
    WO("Para ser sincero, isso não é boa ideia.", ["Eerlijk","gezegd","is","dat","geen","goed","idee"], "Inversão.", ["v-eerlijk-gezegd"]),
    FE(["Eerlijk","gezegd","ik","vind","het","saai."], 2, "vind ik", "Inversão: Eerlijk gezegd vind ik het saai.", ["v-eerlijk-gezegd"]),
    LI("Om eerlijk te zijn, vond ik de film niet zo goed.", ["Om eerlijk te zijn(,) vond ik de film niet zo goed"], "Para ser sincero, não achei o filme grande coisa.", "om eerlijk te zijn.", ["v-eerlijk-gezegd"]),
    AR("kritiek","a crítica","de", "De kritiek.", ["v-kritiek"]),
    FB("Hij bedoelt het niet ___, hij is gewoon direct.", ["bot"], "rude.", ["v-bot"], choices=["bot","direct","eerlijk"], tr="Ele não quer ser rude, é simplesmente direto."),
  ], diff=4, mins=6)

L(3, "Pontualidade e agenda", "Op tijd zijn, afspraken in de agenda, «even plannen».",
  ["Compreender a cultura de horários e planeamento"],
  vocab=[V("v-stipt","stipt","pontual|em ponto","adjective",note="stipt om acht uur = às oito em ponto"), V("v-plannen","plannen","planear|marcar","verb"),
         V("v-spontaan","spontaan","espontâneo","adjective"), V("v-verjaardagskalender","verjaardagskalender","calendário de aniversários","noun","de")],
  ex=[("De vergadering begint stipt om negen uur.","A reunião começa às nove em ponto."),("Zullen we iets plannen voor volgende maand?","Marcamos alguma coisa para o mês que vem?"),("Nederlanders zijn niet zo spontaan.","Os neerlandeses não são muito espontâneos."),("De verjaardagskalender hangt op de wc.","O calendário de aniversários está pendurado na casa de banho.")],
  review=["v-op-tijd","v-agenda","v-afspraak","v-te-laat"],
  cefr=C, exs=[
    MA([("stipt","em ponto"),("plannen","planear"),("spontaan","espontâneo"),("verjaardagskalender","calendário de aniversários")], "Agenda.", ["v-stipt","v-plannen","v-spontaan","v-verjaardagskalender"]),
    TR("pt-nl","A reunião começa às nove em ponto.", ["De vergadering begint stipt om negen uur","De vergadering begint om negen uur stipt"], "stipt.", ["v-stipt"]),
    TR("pt-nl","Marcamos alguma coisa para o mês que vem?", ["Zullen we iets plannen voor volgende maand","Zullen we iets afspreken voor volgende maand"], "plannen.", ["v-plannen"]),
    MC("Um amigo neerlandês diz «Ik kijk even in mijn agenda». Isso é…", ["*normal: muitos combinam até jantares com semanas de antecedência","uma forma de recusar|Não necessariamente.","falta de interesse|Não."], "Cultura da agenda.", ["v-plannen"]),
    MC("Onde se pendura tradicionalmente o verjaardagskalender?", ["*Na casa de banho (wc)","Na porta da rua|Não.","No carro|Não."], "Curiosidade cultural.", ["v-verjaardagskalender"]),
    MC("Convite para jantar às 18h00. Chega…", ["*às 18h00 ou poucos minutos depois","às 19h30|Muito tarde; o jantar já começou.","às 17h00|Cedo demais."], "Pontualidade.", ["v-stipt"]),
    FE(["De","les","begint","stipt","op","negen","uur."], 4, "om", "Com horas usa-se «om»: stipt om negen uur.", ["v-stipt"]),
    LI("Kunnen we volgende week iets plannen?", ["Kunnen we volgende week iets plannen"], "Podemos marcar alguma coisa para a semana?", "plannen.", ["v-plannen"]),
    FB("Mijn Portugese vrienden zijn veel ___: ze bellen en komen meteen langs.", ["spontaner"], "Comparativo de spontaan.", ["v-spontaan"], choices=["spontaner","spontaan","spontaanst"], tr="Os meus amigos portugueses são muito mais espontâneos: ligam e aparecem logo."),
    CO("text","Een avondje uit", "Als je in Nederland met vrienden wilt afspreken, moet je vaak een paar weken vooruit plannen. Iedereen heeft een volle agenda. Een etentje begint meestal om zes uur, en wie een kwartier te laat komt, stuurt even een appje. Spontaan langskomen gebeurt wel, maar vooral bij familie of goede vrienden.",
       [("A que horas começa normalmente um jantar?", ["*Às seis","Às nove","À meia-noite"]),("O que faz quem se atrasa 15 minutos?", ["*Manda uma mensagem","Não diz nada","Cancela"])],
       "vooruit plannen = planear com antecedência.", ["v-plannen","v-spontaan"]),
  ], diff=4, mins=7)

L(4, "Dinheiro e partilhar a conta", "Ieder betaalt voor zich. Een Tikkie sturen.",
  ["Compreender hábitos neerlandeses com dinheiro"],
  vocab=[V("v-delen","delen","dividir|partilhar","verb"), V("v-zuinig","zuinig","poupado|económico","adjective"),
         V("v-ieder-voor-zich","ieder betaalt voor zich","cada um paga o seu","expression"), V("v-trakteren","trakteren","oferecer (pagar a outros)","verb",note="Ik trakteer! = Eu pago!")],
  ex=[("Zullen we de rekening delen?","Dividimos a conta?"),("Ieder betaalt voor zich.","Cada um paga o seu."),("Ik trakteer vandaag!","Hoje pago eu!"),("Nederlanders staan bekend als zuinig.","Os neerlandeses têm fama de poupados.")],
  gram=[G("g-geld-cultuur","Partilhar despesas","É normal dividir a conta ou pagar cada um o seu (**ieder voor zich**). Depois, quem pagou tudo envia um **Tikkie** (pedido de pagamento). No aniversário, quem faz anos é quem **trakteert** (oferece bolo aos colegas).",
    [("Ik stuur je straks een Tikkie.","Daqui a pouco mando-te um Tikkie.")],
    "Em Portugal oferece-se mais vezes a conta; aqui dividir não é sinal de avareza.")],
  review=["v-rekening","v-tikkie","v-betalen"],
  cefr=C, exs=[
    MA([("delen","dividir"),("zuinig","poupado"),("ieder betaalt voor zich","cada um paga o seu"),("trakteren","oferecer")], "Dinheiro.", ["v-delen","v-zuinig","v-ieder-voor-zich","v-trakteren"]),
    TR("pt-nl","Dividimos a conta?", ["Zullen we de rekening delen","Delen we de rekening"], "delen.", ["v-delen"]),
    TR("pt-nl","Hoje pago eu!", ["Ik trakteer vandaag","Vandaag trakteer ik"], "trakteren.", ["v-trakteren"]),
    TR("nl-pt","Nederlanders staan bekend als zuinig.", ["Os neerlandeses têm fama de poupados","Os neerlandeses são conhecidos por serem poupados"], "bekend staan als.", ["v-zuinig"]),
    MC("No seu aniversário, no trabalho, é costume…", ["*levar bolo ou doces para os colegas (trakteren)","esperar que os colegas paguem o almoço|Não é o costume.","não dizer a ninguém|Não."], "Trakteren.", ["v-trakteren"]),
    MC("Um amigo pagou o jantar e envia um Tikkie. Deve…", ["*pagar a sua parte pelo link","ficar ofendido|É normal.","ignorar|Não."], "Tikkie.", ["v-tikkie"]),
    FE(["Ieder","betaalt","voor","hem."], 3, "zich", "Expressão fixa: ieder betaalt voor zich.", ["v-ieder-voor-zich"]),
    LI("Zullen we het gewoon delen?", ["Zullen we het gewoon delen"], "Dividimos simplesmente?", "delen.", ["v-delen"]),
    DL([("Collega","Ik ben vandaag jarig, dus ik trakteer op taart!","Hoje faço anos, por isso ofereço bolo!"),("Carla","")], ["*Gefeliciteerd! Wat lief, dank je!","Wat zuinig!|Inadequado.","Hoeveel moet ik betalen?|Ela está a oferecer."], "Agradecer.", ["v-trakteren"]),
    FB("Mijn opa is erg ___: hij gooit nooit iets weg.", ["zuinig"], "Poupado.", ["v-zuinig"], choices=["zuinig","gezellig","direct"], tr="O meu avô é muito poupado: nunca deita nada fora."),
  ], diff=4, mins=6)

L(5, "Estereótipos e realidade", "Klopt het dat…? Dat is een vooroordeel.",
  ["Discutir estereótipos com nuance"],
  vocab=[V("v-vooroordeel","vooroordeel","preconceito|estereótipo","noun","het","vooroordelen"), V("v-cliche","cliché","cliché","noun","het"),
         V("v-gemiddeld","gemiddeld","em média","adverb"), V("v-generaliseren","generaliseren","generalizar","verb")],
  ex=[("Klopt het dat alle Nederlanders lang zijn?","É verdade que todos os neerlandeses são altos?"),("Dat is een cliché.","Isso é um cliché."),("Gemiddeld zijn ze wel lang.","Em média são de facto altos."),("Je moet niet generaliseren.","Não se deve generalizar.")],
  review=["v-dat-klopt","v-deels","v-volgens-mij"],
  cefr=C, exs=[
    MA([("vooroordeel","preconceito"),("cliché","cliché"),("gemiddeld","em média"),("generaliseren","generalizar")], "Estereótipos.", ["v-vooroordeel","v-cliche","v-gemiddeld","v-generaliseren"]),
    WO("É verdade que todos os neerlandeses são altos?", ["Klopt","het","dat","alle","Nederlanders","lang","zijn?"], "dat + verbo no fim.", ["v-dat-klopt"]),
    TR("pt-nl","Não se deve generalizar.", ["Je moet niet generaliseren","Je mag niet generaliseren","Men moet niet generaliseren"], "generaliseren.", ["v-generaliseren"]),
    TR("nl-pt","Gemiddeld zijn ze wel lang.", ["Em média são de facto altos","Em média são altos, sim"], "gemiddeld; wel = de facto.", ["v-gemiddeld"]),
    AR("vooroordeel","o preconceito","het", "Het vooroordeel.", ["v-vooroordeel"]),
    MC("«Alle Portugezen eten elke dag bacalhau» é…", ["*een cliché / vooroordeel","een feit|Não.","een recept|Não."], "Generalização.", ["v-cliche"]),
    CO("text","Kloppen de clichés?", "Over Nederlanders bestaan veel clichés: ze fietsen altijd, ze eten elke dag kaas en ze zijn zuinig. Een deel klopt: er zijn meer fietsen dan mensen en gemiddeld zijn Nederlanders de langste mensen ter wereld. Maar niet iedereen houdt van kaas, en lang niet iedereen draagt klompen – eigenlijk bijna niemand!",
       [("O que é verdade segundo o texto?", ["*Há mais bicicletas do que pessoas","Todos usam socas","Todos adoram queijo"]),("Quem usa socas (klompen) hoje?", ["*Quase ninguém","Toda a gente","Só as crianças"])],
       "klompen = socas de madeira.", ["v-cliche","v-gemiddeld"]),
    FE(["Gemiddeld","Nederlanders","zijn","erg","lang."], 1, "zijn Nederlanders", "Inversão depois de gemiddeld: Gemiddeld zijn Nederlanders…", ["v-gemiddeld"]),
    LI("Dat is een vooroordeel, dat klopt niet.", ["Dat is een vooroordeel(,) dat klopt niet"], "Isso é um preconceito, não é verdade.", "vooroordeel.", ["v-vooroordeel"]),
    SW("Escreva 2–3 frases sobre um cliché acerca de Portugal ou dos Países Baixos e diga se concorda.", ["Men zegt dat Portugezen altijd te laat komen. Dat klopt deels, maar je moet niet generaliseren."], ["Apresentou o cliché (**men zegt dat…**)", "Opinião com nuance (**deels / gemiddeld**)", "Verbo no fim depois de dat"], 15, "Discutir estereótipos.", ["v-generaliseren","v-cliche"]),
  ], diff=4, mins=7)

W()
